import csv
import io


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    reader = csv.reader(
        io.StringIO(raw_csv.lstrip("\ufeff"), newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )

    records = []
    try:
        for record in reader:
            if record and any(value.strip() for value in record):
                records.append(record)
    except csv.Error:
        pass

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 3
    header_index = next(
        (i for i, record in enumerate(records) if len(record) == expected_width),
        0,
    )
    columns = records[header_index]
    width = len(columns)

    rows = []
    for record in records[header_index + 1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
